<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{frontdeskRecoveryTarget}from'./frontdesk-recovery-target';
const props=defineProps<{pending:any;clinicId:string;accountId:string;employeeId:string}>(),emit=defineEmits(['completed','retry','unauthorized']),checking=ref(false),state=ref(''),error=ref(''),checked=ref(false);let generation=0,alive=true;
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const signature=()=>JSON.stringify([props.accountId,props.employeeId,props.clinicId,props.pending]);
watch(signature,()=>{generation++;checking.value=false;state.value='';error.value='';checked.value=false;},{flush:'sync'});onBeforeUnmount(()=>{alive=false;generation++;});
async function verify(){if(checking.value)return;const p=props.pending,b=p?.body,target=frontdeskRecoveryTarget(p);if(!target||![props.clinicId,b?.requestId,target.id].every(x=>typeof x==='string'&&uuid.test(x))){error.value='原请求编号或办理对象信息不完整，请保留缓存核查。';return;}const gen=++generation,key=signature(),current=()=>alive&&gen===generation&&key===signature();checking.value=true;state.value='';checked.value=false;error.value='';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const action=['reschedule','cancel','contact'].includes(target.kind),r=await fetch('/api/v1/frontdesk/'+(target.kind==='book'?'appointment-commands/':action?'appointment-action-commands/':'commands/')+b.requestId+'?'+new URLSearchParams(target.kind==='book'?{clinicId:props.clinicId,scheduleId:target.id}:action?{clinicId:props.clinicId,appointmentId:target.id,kind:target.kind}:{clinicId:props.clinicId,targetId:target.id,kind:target.kind}),{credentials:'same-origin',signal:controller.signal}),v=await r.json();if(!current())return;if(!r.ok){if(r.status===401)emit('unauthorized');throw Error(v.message||'核实失败，请保留原请求。');}if(String(v.requestId).toLowerCase()!==b.requestId.toLowerCase()||String(v.clinicId).toLowerCase()!==props.clinicId.toLowerCase()||(target.kind==='book'?String(v.scheduleId).toLowerCase()!==target.id.toLowerCase():String(action?v.appointmentId:v.targetId).toLowerCase()!==target.id.toLowerCase()||v.kind!==target.kind)||!['completed','not_found'].includes(v.state)||v.state==='completed'&&(!uuid.test(v.resultId)||target.kind!=='contact'&&(!uuid.test(v.revisionId)||!Number.isSafeInteger(v.version)||v.version<1)||!Number.isFinite(Date.parse(v.completedAt))))throw Error('核实回复不匹配，请保留原请求。');state.value=v.state;if(v.state==='completed')emit('completed',p);}catch(e){if(current())error.value=(e as Error).message||'核实暂不可用，请保留原请求。';}finally{clearTimeout(timer);if(current())checking.value=false;}}
function retry(){if(!checking.value&&state.value==='not_found'&&checked.value)emit('retry',props.pending);}
</script>
<template><section class="b-card f-booking-recovery"><h3>核实原前台操作</h3><p>先按当前办理诊所核实原办理对象和请求号。查询不会重复办理。</p><button type="button" class="b-button small" :disabled="checking" @click="verify">{{checking?'正在核实原预约…':'只读核实原前台操作'}}</button><p v-if="error" class="b-alert error" role="alert">{{error}}</p><template v-if="state==='not_found'"><p>暂未查到匹配的已保存结果，不代表请求未在处理中。核对原诊所和原请求后，可使用同一请求重试。</p><label class="b-checkbox"><input type="checkbox" v-model="checked"/><span>已核对原诊所及操作，仅重试原请求，不另办一笔。</span></label><button type="button" class="b-button outline small" :disabled="!checked||checking" @click="retry">按原请求重试操作</button></template></section></template>
<style scoped>.f-booking-recovery{padding:20px;margin-block:16px}.f-booking-recovery h3{margin-top:0}.f-booking-recovery p{line-height:1.7}</style>
